-- =====================================================
-- SEMILLA: tabla de mapeo de Shoplamp
-- =====================================================
-- Vuelca la hoja «Ahora» de «Base de datos.xlsx», que es el Excel que hoy se
-- edita a mano y del que solo hay una copia. La hoja trae 481 filas con
-- datos y aquí entran 480 (ver el SKU repetido más abajo): un listing de
-- Amazon por fila, tenga o no referencia del ERP.
--
-- Se meten también las 88 filas sin referencia, que no son basura sino
-- listings que todavía no han casado: son exactamente las que hay que
-- arreglar, y dejarlas fuera las volvería invisibles. Las que sí traen
-- referencia son 392 (393 en la hoja, menos la del SKU repetido).
--
-- Los valores vienen ya normalizados con las mismas reglas que
-- lib/types/stock-sync.ts, porque Excel exporta los códigos como número y
-- guardarlos como «50119247.0» rompería el cruce en silencio:
--   - ref_erp: sin ceros a la izquierda, sin el sufijo «.0» y sin separadores.
--   - los EAN: solo dígitos, sin ceros a la izquierda, y vacío (NULL) si se
--     quedan en menos de 8 dígitos, porque entonces es un código interno del
--     ERP y no un EAN.
--   - sku_amazon: TAL CUAL, solo sin el «.0». Aquí no se tocan los ceros a la
--     izquierda ni se quitan guiones: el SKU es la cadena que Amazon espera
--     recibir y «05-NDKE-740Z» no es «5NDKE740Z».
--
-- El client_id se resuelve por el slug, así que esta migración depende de la
-- 106 (que crea las tablas y la fila de Shoplamp).
--
-- ON CONFLICT DO NOTHING contra UNIQUE (client_id, sku_amazon): reejecutarla
-- no duplica ni pisa las correcciones que se hayan hecho a mano desde la
-- pantalla. Para volver a partir del Excel hay que borrar los mapeos del
-- cliente primero.
--
-- El Excel trae un SKU repetido, que aquí no cabe porque el SKU es la clave
-- del listing. Se queda la primera aparición y se descarta la segunda:
--   fila 226 de la hoja: SKU 80009070, ya estaba en la fila 89. Las dos
--   filas dicen lo mismo (misma ref, mismo ASIN, mismo EAN) y solo cambian
--   en metodo_match («SKU con ceros» en vez de «SKU = ref ERP»), así que no
--   se pierde ningún dato.
--
-- Las mismas filas están en supabase/seed/stock_mappings_shoplamp.csv, por
-- si algún día hay que reimportarlas desde cero o el fichero crece hasta no
-- caber en el editor SQL. Ese CSV no lleva client_id, así que no se puede
-- subir directo a stock_mappings (la columna es NOT NULL): hay que cargarlo
-- en una tabla de paso y unirla por slug. Con la CLI de Postgres:
--   CREATE TEMP TABLE tmp_map (LIKE public.stock_mappings INCLUDING DEFAULTS);
--   ALTER TABLE tmp_map ALTER COLUMN client_id DROP NOT NULL;
--   \copy tmp_map (ref_erp, sku_amazon, asin, ean_amazon, ean_erp, ean_final,
--     origen_ean, metodo_match, sku_coincide, ean_coincide, todos_ean_erp,
--     situacion_erp, titulo_amazon, is_active, notes)
--     FROM 'supabase/seed/stock_mappings_shoplamp.csv' WITH (FORMAT csv, HEADER true);
--   INSERT INTO public.stock_mappings (client_id, ref_erp, sku_amazon, asin,
--     ean_amazon, ean_erp, ean_final, origen_ean, metodo_match, sku_coincide,
--     ean_coincide, todos_ean_erp, situacion_erp, titulo_amazon, is_active, notes)
--   SELECT c.id, t.ref_erp, t.sku_amazon, t.asin, t.ean_amazon, t.ean_erp,
--     t.ean_final, t.origen_ean, t.metodo_match, t.sku_coincide, t.ean_coincide,
--     t.todos_ean_erp, t.situacion_erp, t.titulo_amazon, t.is_active, t.notes
--   FROM tmp_map t, public.stock_clients c WHERE c.slug = 'shoplamp'
--   ON CONFLICT (client_id, sku_amazon) DO NOTHING;

DO $$
DECLARE v_client UUID;
BEGIN
  -- Guarda por si esto se ejecuta sobre una base donde la 106 aún no ha
  -- pasado: un INSERT contra una tabla que no existe aborta la migración
  -- entera en el editor SQL de Supabase.
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'stock_mappings'
  ) OR NOT EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'stock_clients'
  ) THEN
    RAISE NOTICE 'stock_mappings/stock_clients no existen todavía: ejecuta antes la 106_stock_sync.sql';
    RETURN;
  END IF;

  SELECT id INTO v_client FROM public.stock_clients WHERE slug = 'shoplamp';

  -- Sin esto el INSERT insertaría cero filas y la migración diría que todo
  -- fue bien, que es la peor forma de enterarse de que falta el cliente.
  IF v_client IS NULL THEN
    RAISE EXCEPTION 'No existe el cliente con slug «shoplamp»; ejecuta antes la 106_stock_sync.sql';
  END IF;

  INSERT INTO public.stock_mappings (
    client_id, ref_erp, sku_amazon, asin, ean_amazon, ean_erp, ean_final,
    origen_ean, metodo_match, sku_coincide, ean_coincide, todos_ean_erp,
    situacion_erp, titulo_amazon
